package com.nexusdrive.storage.config;import java.nio.file.Path;import java.util.*;import org.springframework.boot.context.properties.ConfigurationProperties;@ConfigurationProperties(prefix="storage")public class StorageProperties{private Path path=Path.of("./data");private String nodeId="node-1";private List<String> peers=new ArrayList<>();private int replicationFactor=3;private String internalSecret;public Path getPath(){return path;}public void setPath(Path v){path=v;}public String getNodeId(){return nodeId;}public void setNodeId(String v){nodeId=v;}public List<String> getPeers(){return peers;}public void setPeers(List<String> v){peers=v;}public int getReplicationFactor(){return replicationFactor;}public void setReplicationFactor(int v){replicationFactor=v;}public String getInternalSecret(){return internalSecret;}public void setInternalSecret(String v){internalSecret=v;}}
